\begin{definition}\label{def:gap}
Let $M$ be an $n \times n$ real symmetric random matrix with eigenvalues $\lambda_1 \geq \lambda_2 \geq \cdots \geq \lambda_n$. The \emph{spectral gap} of $M$ is defined as
$$\mathrm{gap}(M) := \lambda_1 - \lambda_2.$$
\end{definition}

\begin{theorem}[Main Theorem]\label{thm:main}
Let $M$ be an $n \times n$ Wigner matrix with sub-gaussian entries. Assume $n \geq n_0$ for some absolute constant $n_0$. Then
$$\mathrm{gap}(M) \geq \frac{c}{n}$$
with probability at least $1 - e^{-n}$, where $c > 0$ is an absolute constant.
\end{theorem}

\begin{lemma}\label{lem:trace}
For any $n \times n$ real symmetric matrix $A$,
$$\sum_{i=1}^{n} \lambda_i^2 = \mathrm{tr}(A^2).$$
\end{lemma}
